//! Golden test of the placement modifiers against the real vanilla classes (fixtures generated by
//! `tests/oracle/PlacementOracle.java` and `tests/oracle/PlacementCodecOracle.java`):
//! * `placement_codec.txt`: whether `PlacementModifier.CODEC` accepts each JSON (accept/reject edge cases per modifier),
//! * `placement_golden.txt`: for every placed feature of the vanilla data pack (273) the PLACEMENT chain only (the loop of
//!   `FeaturePlacer.place`, without the feature) at 6 origins x 2 regions x 3 seeds over the shared synthetic world, with and
//!   without the biome check: the ordered final positions and the random's next long afterwards,
//! * the same for the chains of `placement_synthetic.json` (modifier types and parameters the data pack never uses).

use crate::common::feature_harness::*;
use mc_core::ident::Identifier;
use mc_core::math::java::java_string_hash;
use mc_core::pos::BlockPos;
use mc_core::random::{LegacyRandomSource, RandomSource, XoroshiroRandomSource};
use mc_game::world::level::levelgen::codec::LoadResult;
use mc_game::world::level::levelgen::placement::{
    PlacementContext, PlacementModifier, decode_modifier,
};
use mc_game::world::level::levelgen::registries::{Cells, DecodeCtx};
use mc_world::status::ChunkStatus;
use mc_worldgen::biome::PlacedFeatureRef;
use mc_worldgen::data::{FsDataSource, WorldgenDataSource};
use serde_json::Value;
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;

fn data_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../ref/src/data")
}

fn fixture(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    if path.extension().is_some_and(|e| e == "gz") {
        mc_testkit::read_gz(&path)
    } else {
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
    }
}

fn decode(json: &Value) -> LoadResult<Arc<dyn PlacementModifier>> {
    let source: Arc<dyn WorldgenDataSource> = Arc::new(FsDataSource::new(data_root()));
    let cells = Cells::new(source);
    let ctx = DecodeCtx {
        worldgen: &WORLD.worldgen,
        biomes: &WORLD.biomes,
        cells: &cells,
    };
    decode_modifier(json, &ctx)
}

#[test]
fn placement_modifier_codec_matches_vanilla() {
    let mut cases = 0;
    let mut failures = Vec::new();
    for line in fixture("placement_codec.txt").lines() {
        let (verdict, json) = line.split_once('\t').expect("verdict<TAB>json");
        let value: Value = serde_json::from_str(json).unwrap_or_else(|e| panic!("{json}: {e}"));
        let result = decode(&value);
        let ours = if result.is_ok() { "OK" } else { "ERR" };
        if ours != verdict {
            failures.push(format!(
                "vanilla {verdict}, ours {ours} ({}): {json}",
                result.err().map(|e| e.to_string()).unwrap_or_default()
            ));
        }
        cases += 1;
    }
    assert!(
        failures.is_empty(),
        "{} of {cases} codec cases differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(cases >= 150);
}

/// `FeaturePlacer.place` minus the feature: the positions that would reach `feature.place`, in order.
fn chain(
    modifiers: &[Arc<dyn PlacementModifier>],
    context: &PlacementContext<'_>,
    random: &mut dyn RandomSource,
    origin: BlockPos,
) -> Vec<BlockPos> {
    if modifiers.is_empty() {
        return vec![origin];
    }
    let mut result = Vec::new();
    let mut positions = vec![origin];
    let mut indices = vec![0usize];
    let mut modified = Vec::new();
    while let Some(pos) = positions.pop() {
        let index = indices.pop().expect("parallel to positions");
        modifiers[index].modify(context, random, pos, &mut modified);
        let next = index + 1;
        if next < modifiers.len() {
            for p in modified.iter().rev() {
                positions.push(*p);
                indices.push(next);
            }
        } else {
            result.extend_from_slice(&modified);
        }
        modified.clear();
    }
    result
}

struct Feature {
    id: Identifier,
    /// The chain tests `would_survive`, i.e. the concrete block classes' `canSurvive` (blocks being ported separately).
    needs_can_survive: bool,
    /// The decoded `placement` list; `without_biome` has the `minecraft:biome` entries removed.
    with_biome: Vec<Arc<dyn PlacementModifier>>,
    without_biome: Vec<Arc<dyn PlacementModifier>>,
}

fn load_placed_features() -> HashMap<String, Feature> {
    let dir = data_root().join("minecraft/worldgen/placed_feature");
    let mut out = HashMap::new();
    for entry in std::fs::read_dir(&dir).expect("placed_feature dir") {
        let path = entry.expect("dir entry").path();
        let name = path
            .file_stem()
            .expect("stem")
            .to_string_lossy()
            .to_string();
        let json: Value =
            serde_json::from_str(&std::fs::read_to_string(&path).expect("read")).expect("json");
        let placement = json["placement"].as_array().expect("placement list");
        let decode_all = |keep_biome: bool| -> Vec<Arc<dyn PlacementModifier>> {
            placement
                .iter()
                .filter(|m| keep_biome || m["type"] != "minecraft:biome")
                .map(|m| decode(m).unwrap_or_else(|e| panic!("{name}: {e}")))
                .collect()
        };
        let id = Identifier::with_default_namespace(&name).expect("id");
        let needs_can_survive = json["placement"].to_string().contains("would_survive");
        out.insert(
            format!("minecraft:{name}"),
            Feature {
                id,
                needs_can_survive,
                with_biome: decode_all(true),
                without_biome: decode_all(false),
            },
        );
    }
    let synthetic: Value =
        serde_json::from_str(&fixture("placement_synthetic.json")).expect("synthetic json");
    for entry in synthetic.as_array().expect("array") {
        let name = format!("synthetic:{}", entry["name"].as_str().expect("name"));
        let modifiers: Vec<Arc<dyn PlacementModifier>> = entry["placement"]
            .as_array()
            .expect("placement")
            .iter()
            .map(|m| decode(m).unwrap_or_else(|e| panic!("{name}: {e}")))
            .collect();
        let id = Identifier::with_default_namespace("synthetic").expect("id");
        out.insert(
            name,
            Feature {
                id,
                needs_can_survive: false,
                with_biome: modifiers.clone(),
                without_biome: modifiers,
            },
        );
    }
    out
}

/// Chains that do not depend on any concrete block class.
#[test]
fn placement_chains_match_vanilla() {
    run_chains(false);
}

/// The chains with a `would_survive` predicate (`canSurvive` of the sapling/plant block classes).
#[test]
fn placement_chains_with_would_survive_match_vanilla() {
    run_chains(true);
}

fn run_chains(can_survive: bool) {
    let features = load_placed_features();
    assert_eq!(features.len(), 273 + 50);
    let mut compared = 0usize;
    let mut skipped = 0usize;
    let mut nonempty = 0usize;
    let mut failures: Vec<String> = Vec::new();
    let text = fixture("placement_golden.txt.gz");
    let mut lines = text.lines().peekable();
    while let Some(header) = lines.next() {
        let h: Vec<&str> = header.split(' ').collect();
        assert_eq!(h[0], "R", "{header}");
        let (seed, cx, cz): (i64, i32, i32) = (
            h[1].parse().unwrap(),
            h[2].parse().unwrap(),
            h[3].parse().unwrap(),
        );
        let mut origins = Vec::new();
        while lines.peek().is_some_and(|l| l.starts_with("O ")) {
            let o: Vec<i32> = lines.next().unwrap()[2..]
                .split(' ')
                .map(|v| v.parse().unwrap())
                .collect();
            origins.push(BlockPos::new(o[0], o[1], o[2]));
        }
        let mut synth = SynthRegion::new(seed, cx, cz, ChunkStatus::Features, 2);
        let env = synth.env.clone();
        let level = synth.level();
        while lines.peek().is_some_and(|l| !l.starts_with("R ")) {
            let line = lines.next().unwrap();
            let f: Vec<&str> = line.split(' ').collect();
            let (name, mode, oi) = (f[0], f[1], f[2].parse::<usize>().unwrap());
            let feature = &features[name];
            if feature.needs_can_survive != can_survive {
                continue;
            }
            if f[3] == "EXC" {
                skipped += 1;
                continue;
            }
            let origin = origins[oi];
            let rs = h_seed(seed, cx, cz, oi, name);
            let mut random: Box<dyn RandomSource> = if oi % 2 == 1 {
                Box::new(LegacyRandomSource::new(rs))
            } else {
                Box::new(XoroshiroRandomSource::new(rs))
            };
            let key = PlacedFeatureRef::Named(feature.id.clone());
            let biome_check = mode == "b";
            let context = PlacementContext::new(&level, &env, biome_check.then_some(&key));
            let modifiers = if biome_check {
                &feature.with_biome
            } else {
                &feature.without_biome
            };
            let result = chain(modifiers, &context, &mut *random, origin);
            let mut acc = 0i64;
            for p in &result {
                acc = mix64(acc ^ p.as_long());
            }
            let ours = format!("{} {:x} {}", result.len(), acc as u64, random.next_long());
            compared += 1;
            if !result.is_empty() {
                nonempty += 1;
            }
            let expected = f[3..].join(" ");
            if ours != expected {
                failures.push(format!("{name} {mode} seed {seed} chunk ({cx},{cz}) origin {origin:?}: vanilla `{expected}`, ours `{ours}`"));
            }
        }
    }
    if let Some(path) = std::env::var_os("PLACEMENT_GOLDEN_DUMP") {
        std::fs::write(path, failures.join("\n")).expect("dump failures");
    }
    let mut names: Vec<&str> = failures
        .iter()
        .map(|f| f.split(' ').next().unwrap())
        .collect();
    names.dedup();
    assert!(
        failures.is_empty(),
        "{} of {compared} placement chains differ, in {} features ({}):\n{}",
        failures.len(),
        names.len(),
        names.join(" "),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    if !can_survive {
        assert_eq!(compared + skipped, 6 * 6 * (210 * 2 + 50));
        assert!(
            nonempty > 3000,
            "only {nonempty} chains produced positions: the test does not exercise the modifiers"
        );
    } else {
        assert_eq!(compared + skipped, 6 * 6 * 63 * 2);
    }
    eprintln!(
        "{compared} chains compared ({nonempty} with positions), {skipped} skipped (vanilla threw)"
    );
}

/// `FeatureOracleBase.h(seed, cx, cz, oi * 1000003L + id.hashCode())`.
fn h_seed(seed: i64, cx: i32, cz: i32, oi: usize, id: &str) -> i64 {
    h(
        seed,
        i64::from(cx),
        i64::from(cz),
        (oi as i64)
            .wrapping_mul(1000003)
            .wrapping_add(i64::from(java_string_hash(id))),
    )
}
